<script>const customer=document.getElementById('customer_party_id'),body=document.getElementById('advance-sources');const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};function totals(){let available=0,selected=0;body.querySelectorAll('tr').forEach(r=>available+=Number(r.dataset.available||0));body.querySelectorAll('[data-amount]:not(:disabled)').forEach(i=>selected+=Number(i.value||0));document.getElementById('available-total').value=available.toFixed(2);document.getElementById('selected-total').value=selected.toFixed(2);document.getElementById('remaining-total').value=(available-selected).toFixed(2);document.getElementById('return-amount').value=selected.toFixed(2)}async function loadSources(){if(!customer.value){body.innerHTML='<tr><td colspan="9" class="et378-empty">Select a customer to load available advance sources.</td></tr>';totals();return}body.innerHTML='<tr><td colspan="9" class="et378-empty">Loading available advance sources...</td></tr>';try{const r=await fetch('{{ route('accounting.customer-advance-returns.sources') }}?party_id='+encodeURIComponent(customer.value));if(!r.ok)throw new Error('source request failed');const j=await r.json();if(!(j.sources||[]).length){body.innerHTML='<tr><td colspan="9" class="et378-empty">No returnable customer advance is currently available.</td></tr>';totals();return}body.replaceChildren();for(const s of j.sources){const i=body.children.length,tr=document.createElement('tr');tr.dataset.available=Number(s.available_amount||0);tr.innerHTML='<td>'+esc(s.source_number)+'</td><td>'+esc(s.advance_source_type)+'</td><td>'+esc(s.source_date)+'</td><td>'+esc(s.booking_id||'')+'</td><td>'+Number(s.original_amount||0).toFixed(2)+'</td><td>'+Number(s.adjusted_amount||0).toFixed(2)+'</td><td>'+Number(s.returned_amount||0).toFixed(2)+'</td><td>'+Number(s.available_amount||0).toFixed(2)+'</td><td><input type="checkbox" data-select><input type="number" step="0.01" min="0.01" max="'+Number(s.available_amount||0)+'" disabled data-amount name="allocations['+i+'][amount]"><input type="hidden" disabled data-source name="allocations['+i+'][advance_source_type]" value="'+esc(s.advance_source_type)+'"><input type="hidden" disabled data-source name="allocations['+i+'][advance_source_id]" value="'+Number(s.advance_source_id)+'"></td>';body.append(tr)}totals()}catch(error){body.innerHTML='<tr><td colspan="9" class="et378-empty">Unable to load advance sources. Please try again.</td></tr>';totals()}}customer.addEventListener('change',loadSources);body.addEventListener('change',e=>{if(e.target.matches('[data-select]')){const r=e.target.closest('tr');r.classList.toggle('is-selected',e.target.checked);r.querySelectorAll('[data-source],[data-amount]').forEach(x=>x.disabled=!e.target.checked);totals()}});body.addEventListener('input',totals);document.querySelector('[name=payment_proof]')?.addEventListener('change',e=>document.querySelector('[data-proof-label]').textContent=e.target.files?.[0]?.name||'No file selected');loadSources();</script>@endsection
